import { SplitButton } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
const Download = (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={1.8}
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
    <polyline points="7 10 12 15 17 10" />
    <line x1="12" y1="15" x2="12" y2="3" />
  </svg>
);
const exportOptions = [
  { id: 'pdf', label: 'PDF', hint: '.pdf' },
  { id: 'csv', label: 'CSV', hint: '.csv' },
  { id: 'markdown', label: 'Markdown', hint: '.md' },
  { id: 'json', label: 'JSON', hint: '.json' },
];
export function Example() {
  const args: Pick<
    ComponentProps<typeof SplitButton>,
    | 'label'
    | 'defaultOptionId'
    | 'leadingIcon'
    | 'size'
    | 'variant'
    | 'menuAlign'
    | 'options'
  > = {
    label: 'Export',
    defaultOptionId: 'pdf',
    leadingIcon: Download,
    size: 'md',
    variant: 'secondary',
    menuAlign: 'end',
    options: exportOptions,
  };
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('No export started.');
  function runDefault() {
    setLoading(true);
    setMessage('Exporting PDF…');
    window.setTimeout(() => {
      setLoading(false);
      setMessage('PDF exported.');
    }, 700);
  }
  return (
    <div>
      <SplitButton
        {...args}
        loading={loading}
        onClick={runDefault}
        onSelect={(id) =>
          setMessage(
            `${id.toUpperCase()} chosen. The main button now exports in this format.`,
          )
        }
      />
      <p
        role="status"
        aria-live="polite"
        style={{ marginTop: 16, color: 'var(--ink-2)' }}
      >
        {message}
      </p>
    </div>
  );
}

import { SplitButton } from '@refy-design/web';
import { useState } from 'react';
function download(text: string, name: string) {
  const url = URL.createObjectURL(
    new Blob([text], { type: 'text/plain;charset=utf-8' }),
  );
  const link = document.createElement('a');
  link.href = url;
  link.download = name;
  link.click();
  URL.revokeObjectURL(url);
}
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function SplitButtonExample() {
  const [status, setStatus] = useState('');
  const exportFile = (format: string) => {
    download(
      format === 'JSON'
        ? JSON.stringify({ materials: ['Content guide', 'Visual references'] }, null, 2)
        : 'material\nContent guide\nVisual references',
      `materials.${format.toLowerCase()}`,
    );
    setStatus(`${format} file ready to download.`);
  };
  return (
    <div style={stack}>
      <SplitButton
        label="Export"
        options={['CSV', 'JSON'].map((format) => ({
          id: format,
          label: format,
          onSelect: () => exportFile(format),
        }))}
      />
      <p role="status">
        {status || 'Choose the format and export the local materials.'}
      </p>
    </div>
  );
}
export function Example() {
  return <SplitButtonExample />;
}
